#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "magick.h"

size_t RegisterJPEGImage(void) {
    static const char *jpeg_version = "6b";
    static MagickInfo *magick_info;
    size_t size = 0;

    magick_info = AcquireMagickInfo("JPEG", &size);
    if (magick_info == NULL)
        return 0;

    SetMagickInfo(magick_info, "JPE", NULL, NULL, NULL, MagickTrue, MagickTrue, NULL, "image/jpeg", "JPEG image format", 0, NULL);
    SetMagickInfo(magick_info, "JPEG", NULL, NULL, NULL, MagickTrue, MagickTrue, NULL, "image/jpeg", "JPEG image format", 0, NULL);
    SetMagickInfo(magick_info, "JPG", NULL, NULL, NULL, MagickTrue, MagickTrue, NULL, "image/jpeg", "JPEG image format", 0, NULL);
    SetMagickInfo(magick_info, "JPS", NULL, NULL, NULL, MagickTrue, MagickTrue, NULL, "image/jpeg", "JPEG image format", 0, NULL);
    SetMagickInfo(magick_info, "PJPEG", NULL, NULL, NULL, MagickTrue, MagickTrue, NULL, "image/jpeg", "JPEG image format", 0, NULL);

    if (jpeg_version != NULL) {
        char *version = (char *)malloc(32);
        if (version != NULL) {
            sprintf(version, "JPEG v%s", jpeg_version);
            magick_info->version = version;
        }
    }

    (void)RegisterMagickInfo(magick_info);

    return size;
}
